const players = {};
function setFrame(key, idx) {
  idx = parseInt(idx);
  document.getElementById('img_' + key).src = FRAMES[key][idx];
  document.getElementById('sl_' + key).value = idx;
  document.getElementById('tl_' + key).textContent = 't = ' + FT[idx].toFixed(0) + ' s';
}
function togglePlay(key) {
  const btn = document.getElementById('play_' + key);
  if (players[key]) { clearInterval(players[key]); players[key] = null; btn.innerHTML = '&#9654;'; return; }
  btn.innerHTML = '&#10074;&#10074;';
  players[key] = setInterval(() => {
    let i = (parseInt(document.getElementById('sl_' + key).value) + 1) % FT.length;
    setFrame(key, i);
  }, 350);
}

